/* Print options and a live paper preview, independently implemented from the observed print page. */
(function(){
 'use strict';
 const defaults=()=>({view:'cards',style:'eco',gangPosition:'before',gangCard:true,additional:true,autoHeight:true,recovery:false,inactive:false,inactiveLoadouts:false,xp:false,wounds:false});
 let options=defaults(),printGangId='',handledRoute='';
 const number=v=>Number(v)||0;
 const label=x=>x?.name||x?.equipment_name||x?.fighter_name||'';
 const button=(text,action,value='')=>`<button type="button" class="btn ${options.view===value?'primary':''}" data-mp="${action}" data-value="${value}">${text}</button>`;
 const checkbox=(key,text)=>`<label class="mp-check"><input type="checkbox" data-mp-option="${key}" ${options[key]?'checked':''}><span>${text}</span></label>`;
 const plain=value=>{let node=document.createElement('div');node.innerHTML=String(value||'');return (node.textContent||'').replace(/\s+/g,' ').trim();};
 const rich=value=>window.GangTools?.sanitize?GangTools.sanitize(value||''):esc(value||'').replace(/\n/g,'<br>');
 const array=value=>Array.isArray(value)?value:typeof value==='string'?value.split(',').map(x=>x.trim()).filter(Boolean):[];
 function selectedGang(){return data.gangs.find(g=>g.id===(printGangId||data.printGangId||data.selectedGang));}
 function visibleFighters(g){return (g.fighters||[]).filter(f=>{if(!options.inactive&&['Dead','Retired','Enslaved'].includes(f.status))return false;if(!options.recovery&&f.status==='In Recovery')return false;return true;}).flatMap(f=>{let loadouts=f.loadouts||[],active=loadouts.find(x=>x.active),shown=options.inactiveLoadouts?loadouts:active?[active]:[];if(!shown.length)return [{fighter:f,loadout:null,key:f.id}];return shown.map(loadout=>({fighter:{...f,loadouts:loadouts.map(x=>({...x,active:x.id===loadout.id}))},loadout,key:f.id+':'+loadout.id}));});}
 function items(f){if(window.RosterParity?.activeEquipment)return RosterParity.activeEquipment(f).items;let loadout=f.loadouts?.find(x=>x.active);return loadout?(f.equipment||[]).filter(x=>loadout.equipmentIds?.includes(x.id)):f.equipment||[];}
 function adjusted(f,equipment=items(f)){if(window.RosterParity?.stats)return RosterParity.stats(f,equipment);if(window.FighterParity?.stats)return FighterParity.stats(f);return f.stats||{};}
 function cost(f,equipment=items(f)){return window.RosterParity?.totalCost?RosterParity.totalCost(f,equipment):number(f.ratingCost??f.cost)+equipment.reduce((sum,x)=>sum+number(x.cost),0);}
 function profiles(item){return window.RosterParity?.profiles?RosterParity.profiles(item):window.FighterParity?.equipmentProfiles?FighterParity.equipmentProfiles(item):item.profiles||item.weaponProfiles||item.weapon_profiles||[];}
 function statTable(g,f,equipment=items(f)){let stats=adjusted(f,equipment),keys=['M','WS','BS','S','T','W','I','A',...(g.edition==='N26'?['Sv']:[]),'Ld','Cl','Wil','Int'];return `<table class="mp-stats"><thead><tr>${keys.map(k=>`<th>${k}</th>`).join('')}</tr></thead><tbody><tr>${keys.map(k=>{let value=stats[k];if(value==null||value==='')value='—';else if(k==='M'&&!/["″]$/.test(String(value)))value+='"';else if(['WS','BS','Sv',...(g.edition==='N26'?[]:['I','Ld','Cl','Wil','Int'])].includes(k)&&!/[+—-]$/.test(String(value)))value+='+';return `<td>${esc(value)}</td>`;}).join('')}</tr></tbody></table>`;}
 function weaponTable(g,f,equipment=items(f)){let weapons=equipment.filter(x=>/weapon/i.test(x.equipmentType||x.equipment_type||'')||profiles(x).length),n26=g.edition==='N26',headers=n26?['Weapon','SR','LR','Str','AP','L','Traits']:['Weapon','Rng S','Rng L','Acc S','Acc L','Str','AP','D','Am','Traits'];if(!weapons.length)return '<span class="mp-none">—</span>';return `<table class="mp-weapons"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${weapons.flatMap(item=>{let rows=profiles(item);if(!rows.length)return [`<tr><td colspan="${headers.length}">${esc(item.name)}</td></tr>`];return rows.map(profile=>{let values=n26?[profile.range_short,profile.range_long,profile.strength,profile.ap,profile.lethality]:[profile.range_short,profile.range_long,profile.acc_short,profile.acc_long,profile.strength,profile.ap,profile.damage,profile.ammo];return `<tr><td>${esc(profile.profile_name||item.name)}${item.masterCrafted?' (Master-crafted)':''}</td>${values.map(value=>`<td>${esc(value??'—')}</td>`).join('')}<td>${esc(Array.isArray(profile.traits)?profile.traits.join(', '):profile.traits||'—')}</td></tr>`;});}).join('')}</tbody></table>`;}
 function boxes(count){return Array.from({length:Math.min(100,Math.max(0,number(count)))}).map(()=>'<i class="mp-box" aria-hidden="true"></i>').join('');}
 function tracking(g,f){let stats=adjusted(f),vehicle=(g.vehicles||[]).find(v=>v.crew===f.id||v.fighterId===f.id),crew=(f.subtypes||[]).includes('Crew'),damage=g.edition==='N26'?{name:'Injured',abbr:'I',count:1}:{name:'Flesh Wound',abbr:'FW',count:crew?3:Math.max(0,number(stats.T)-1)},wounds=crew?number(vehicle?.stats?.HP??vehicle?.hullPoints??vehicle?.hull_points):number(stats.W),woundLabel=crew?'HP':'W';let wound=options.wounds?`<div class="mp-tracks">${wounds>1?`<span class="mp-track" data-kind="${woundLabel}"><b>${woundLabel}</b>${boxes(wounds-1)}</span>`:''}<span class="mp-track" data-kind="${damage.abbr}"><b>${damage.abbr}</b>${boxes(damage.count)}</span></div>`:'';let xp=options.xp?`<div class="mp-xp-boxes"><b>XP:</b>${[['SI',6],['OOA',6],['R/A',5],['Ld/Ch',5],['Misc',6],...(options.view==='roster'?[['Participation',1]]:[])].map(([name,count])=>`<span class="mp-track" data-kind="${name}"><b>${name}</b>${boxes(count)}</span>`).join('')}</div>`:'';return wound||xp?`<footer class="mp-track-footer">${wound}${xp}</footer>`:'';}
 function campaignFor(g){return data.campaigns.find(c=>c.members?.some(m=>m.gangId===g.id));}
 function gangFacts(g){let campaign=campaignFor(g),member=campaign?.members.find(m=>m.gangId===g.id),resources=(campaign?.resources||[]).map(r=>[r.name,member?.resources?.[r.id]??r.amount??0]);return [['Rating',rating(g)],['Credits',g.credits],['Wealth',number(g.credits)+rating(g)],['Reputation',g.reputation],...(g.edition==='N26'?[['Trade Points',g.tradePoints]]:[]),...resources,['Gang Size',(g.fighters||[]).filter(f=>!['Dead','Retired'].includes(f.status)).length]];}
 function gangCard(g){let campaign=campaignFor(g),image=g.imageUrl||g.image_url||g.portrait,owner=data.account?.username||data.username||'Local player';return `<article class="mp-paper-card mp-gang-card" data-mp-card="gang"><header class="mp-card-title"><h2>${esc(g.name)}</h2>${image?`<img src="${esc(image)}" alt="${esc(g.name)}">`:''}</header><div class="mp-card-content"><p>Owner: <b>${esc(owner)}</b></p><p>Type: <b>${esc(g.faction)}</b>${g.subtype?' · '+esc(g.subtype):''}</p>${g.origin?`<p>Origin: ${esc(g.origin)}</p>`:''}${g.edition==='N23'?`<p>Alignment: <b>${esc(g.alignment||'Law Abiding')}</b></p>`:''}${g.alliance?`<p>Alliance: ${esc(g.alliance)}</p>`:''}${g.affiliation?`<p>Affiliation: ${esc(g.affiliation)}</p>`:''}${campaign?`<p>Campaign: <b>${esc(campaign.name)}</b></p>`:''}<div class="mp-gang-facts">${gangFacts(g).map(([key,value])=>`<span>${esc(key)}:</span><b>${fmt(value)}</b>`).join('')}</div><p class="mp-print-dates">Created: ${dateText(g.createdAt||g.created_at)} <span>Last Updated: ${dateText(g.updatedAt||g.last_updated)}</span></p></div></article>`;}
 function dateText(value){return value&&!Number.isNaN(new Date(value).getTime())?new Date(value).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'N/A';}
 function additionalCard(g){let campaign=campaignFor(g),territories=(campaign?.territories||[]).filter(t=>t.gangId===g.id),stash=g.stash||[],note=g.notes||g.note;if(!options.additional||!territories.length&&!stash.length&&!plain(note))return '';return `<article class="mp-paper-card mp-additional-card" data-mp-card="additional"><header class="mp-card-title"><h2>Additional Details</h2></header><div class="mp-card-content">${territories.length?`<p><b>Territories:</b> ${territories.map(t=>esc(t.name)+(t.ruined?' (Ruined)':'')).join(', ')}</p>`:''}${stash.length?`<p><b>Stash:</b> ${stash.slice().sort((a,b)=>label(a).localeCompare(label(b))).map(x=>`${esc(label(x))} (${fmt(x.cost)} credits)`).join(', ')}</p>`:''}${plain(note)?`<div><b>Notes:</b><div class="mp-rich-note">${rich(note)}</div></div>`:''}</div></article>`;}
 function fallbackCard(g,f,loadout){let equipment=items(f),wargear=equipment.filter(x=>!profiles(x).length&&!/weapon/i.test(x.equipmentType||x.equipment_type||''));return `<article class="mp-paper-card mp-fighter-fallback"><header class="mp-card-title"><div><h2>${esc(f.name)}</h2><p>${esc(f.type)}${loadout?' · '+esc(loadout.name):''}</p></div><strong>${fmt(cost(f,equipment))}<small>Credits</small></strong></header><div class="mp-card-content">${statTable(g,f,equipment)}${weaponTable(g,f,equipment)}${wargear.length?`<p><b>Wargear:</b> ${wargear.map(x=>esc(x.name)).join(', ')}</p>`:''}${f.skills?.length?`<p><b>Skills:</b> ${f.skills.map(esc).join(', ')}</p>`:''}${f.specialRules?.length?`<p><b>Rules:</b> ${f.specialRules.map(esc).join(', ')}</p>`:''}${f.injuries?.length?`<p><b>Lasting Injuries:</b> ${f.injuries.map(x=>esc(x.name)).join(', ')}</p>`:''}${f.notes?`<div class="mp-rich-note">${rich(f.notes)}</div>`:''}</div></article>`;}
 function fighterCard(g,row){let f=row.fighter,card=window.RosterParity?.card?RosterParity.card(g,f):fallbackCard(g,f,row.loadout),template=document.createElement('template');template.innerHTML=card;template.content.querySelectorAll('.rp-card-menu').forEach(x=>x.remove());template.content.querySelectorAll('*').forEach(node=>{for(let attr of [...node.attributes])if(attr.name.startsWith('data-rp')||['draggable','tabindex','role'].includes(attr.name))node.removeAttribute(attr.name);});template.content.querySelectorAll('button,a').forEach(node=>{let span=document.createElement('span');span.innerHTML=node.innerHTML;node.replaceWith(span);});return `<div class="mp-fighter-slot" data-mp-fighter="${esc(f.id)}" data-mp-loadout="${esc(row.loadout?.id||'')}">${template.innerHTML}${tracking(g,f)}</div>`;}
 function roster(g,rows){return `<section class="mp-roster"><header class="mp-roster-header"><div><h1>${esc(g.name)}</h1><p>${esc(g.faction)}${g.subtype?' ('+esc(g.subtype)+')':''}</p></div><div>${gangFacts(g).map(([key,value])=>`<span><b>${esc(key)}:</b> ${fmt(value)}</span>`).join('')}</div></header><table class="mp-roster-table"><thead><tr><th>ID</th><th>Name</th><th>Weapons</th><th>Wargear, Lasting Injuries &amp; Notes</th></tr></thead><tbody>${rows.map((row,index)=>{let f=row.fighter,equipment=items(f),wargear=equipment.filter(x=>!profiles(x).length&&!/weapon/i.test(x.equipmentType||x.equipment_type||'')),notes=plain(f.notes),preview=notes.length>110?notes.slice(0,110)+'…':notes;return `<tr data-mp-fighter="${esc(f.id)}" data-mp-loadout="${esc(row.loadout?.id||'')}"><td>${index+1}</td><td><div class="mp-roster-name"><b>${esc(f.name)}${row.loadout?' ('+esc(row.loadout.name)+')':''}</b><strong>Rating: ${fmt(cost(f,equipment))}</strong></div><p>${esc(f.type)}${array(f.subtypes).length?' · '+array(f.subtypes).map(esc).join(', '):''}</p>${statTable(g,f,equipment)}${f.skills?.length?`<p><b>Skills:</b> ${f.skills.map(esc).join(', ')}</p>`:''}</td><td>${weaponTable(g,f,equipment)}</td><td>${wargear.length?`<p><b>Wargear:</b> ${wargear.map(x=>esc(x.name)).join(', ')}</p>`:''}${f.specialRules?.length?`<p><b>Rules:</b> ${f.specialRules.map(esc).join(', ')}</p>`:''}${f.injuries?.length?`<p><b>${f.isSpyrer||f.is_spyrer?'Rig Glitches':'Lasting Injuries'}:</b> ${f.injuries.map(x=>esc(x.name)+(x.hatredTargetName?' ('+esc(x.hatredTargetName)+')':'')).join(', ')}</p>`:''}${preview?`<p><b>Note:</b> ${esc(preview)}</p>`:''}${tracking(g,f)}</td></tr>`;}).join('')}</tbody></table></section>`;}
 function preview(g){let rows=visibleFighters(g);if(options.view==='roster')return roster(g,rows);let gangCards=(options.gangCard?gangCard(g):'')+additionalCard(g);return `<div class="mp-cards mp-${options.style}" data-mp-autosize="${options.autoHeight}">${options.gangPosition==='before'?gangCards:''}${rows.map(row=>fighterCard(g,row)).join('')}${options.gangPosition==='after'?gangCards:''}</div>`;}
 function page(g){return `<div class="mp-print-page"><section class="card mp-options"><h2>Print Options</h2><p class="mp-print-notice"><strong>Note:</strong> Displayed size on this page is indicative only. You can change the scale of your print in your printer settings.</p><div class="mp-option-section"><p>View Mode</p><div class="mp-two">${button('Cards','view','cards')}${button('Roster','view','roster')}</div></div>${options.view==='cards'?`<div class="mp-option-section"><p>Print style</p><label class="mp-style ${options.style==='eco'?'selected':''}"><input type="radio" name="mp-print-style" data-mp-option="style" value="eco" ${options.style==='eco'?'checked':''}><span><b>Eco</b><small>Hide decorative backgrounds to save ink.</small></span></label><label class="mp-style ${options.style==='fancy'?'selected':''}"><input type="radio" name="mp-print-style" data-mp-option="style" value="fancy" ${options.style==='fancy'?'checked':''}><span><b>Fancy</b><small>Include illustrated card backgrounds when printing.</small></span></label></div>`:''}<div class="mp-option-section"><p>Include the following:</p><div class="mp-include-grid">${options.view==='cards'?`<label class="mp-layout">Cards layout<select data-mp-option="gangPosition"><option value="before" ${options.gangPosition==='before'?'selected':''}>Gang cards before fighters</option><option value="after" ${options.gangPosition==='after'?'selected':''}>Gang cards after fighters</option></select></label>${checkbox('gangCard','Gang Card')}${checkbox('additional','Additional Details')}${checkbox('autoHeight','Adjust Cards Height to Content')}`:''}${checkbox('recovery','Fighters in Recovery')}${checkbox('inactive','Inactive Fighters (Killed/Retired/Enslaved)')}${checkbox('inactiveLoadouts','Inactive Fighters Loadouts')}${checkbox('xp','XP Boxes')}${checkbox('wounds',g.edition==='N26'?'Wound/Injured Boxes':'Wound/Flesh Wound Boxes')}</div></div><footer class="mp-options-footer">${button('Cancel','cancel')}${button('Print','print')}</footer></section><div class="mp-preview-window"><div id="mp-print-preview">${preview(g)}</div></div></div>`;}
 function updatePreview(){let g=selectedGang();if(!g)return;let container=document.querySelector('.content');if(container)container.innerHTML=page(g);document.body.classList.toggle('mp-fancy-print',options.view==='cards'&&options.style==='fancy');}
 function open(g){if(!g)return;options=defaults();printGangId=g.id;data.printGangId=g.id;data.selectedGang=g.id;data.view='print';let route='/gang/'+encodeURIComponent(g.id)+'/print';if(location.pathname!==route)history.pushState({mundaPrint:true},'',route);handledRoute=route;closeModal();save();}
 printGang=open;
 window.addEventListener('click',event=>{let target=event.target.closest('[data-mp],[data-ext="print-gang"]');if(!target)return;event.preventDefault();event.stopImmediatePropagation();if(target.dataset.ext==='print-gang'){open(gang());return;}let action=target.dataset.mp;if(action==='view'){options.view=target.dataset.value;updatePreview();}else if(action==='print'){window.print();}else if(action==='cancel'){let g=selectedGang();data.view='gang';if(g){data.selectedGang=g.id;history.pushState({},'','/gang/'+encodeURIComponent(g.id));}handledRoute='';save();}},true);
 document.addEventListener('change',event=>{let target=event.target.closest('[data-mp-option]');if(!target)return;let key=target.dataset.mpOption;if(!(key in options))return;options[key]=target.type==='checkbox'?target.checked:target.value;updatePreview();});
 const oldRender=render;
 render=function(){let route=location.pathname.match(/^\/gang\/([^/]+)\/print\/?$/);if(route&&handledRoute!==location.pathname){let g=data.gangs.find(x=>x.id===decodeURIComponent(route[1]));if(g){printGangId=g.id;data.printGangId=g.id;data.selectedGang=g.id;data.view='print';options=defaults();handledRoute=location.pathname;}}oldRender();let active=data.view==='print',g=selectedGang();document.body.classList.toggle('mp-is-print-page',active);if(active&&g){updatePreview();let crumb=document.querySelector('.crumb');if(crumb)crumb.innerHTML=`<span>⌂</span> / ${esc(g.name)} / <strong>Print</strong>`;}else document.body.classList.remove('mp-fancy-print');};
 window.addEventListener('popstate',()=>{handledRoute='';if(!/\/print\/?$/.test(location.pathname)&&data.view==='print')data.view='gang';render();});
 window.MMPrint={open,preview,visibleFighters,options:()=>({...options}),setOptions:next=>{options={...options,...next};if(data.view==='print')updatePreview();},page};
 render();
})();
